/**
 * ?bench: runs the guided tour and measures what the visitor's machine does
 * with it: frame-time distribution per step, render tier and backend, GPU
 * adapter, screen and render size, stars and bytes streamed. The report is
 * shown at the end, ready to copy into docs/performance.md. Nothing is sent
 * anywhere.
 */
import type { App } from './app';
import { TIER_NAME } from './app';
import { TOUR } from './tour';
import { el } from '../ui/dom';

interface StepStats {
  step: number;
  label: string;
  frames: number;
  p50: number;
  p95: number;
  p99: number;
  max: number;
}

const pct = (a: number[], q: number) => (a.length ? a[Math.min(a.length - 1, Math.floor(q * a.length))] : 0);

function summarise(step: number, times: number[]): StepStats {
  const a = [...times].sort((x, y) => x - y);
  const say = TOUR[step]?.say ?? '';
  return { step, label: say.slice(0, 14) || `第 ${step + 1} 步`, frames: a.length, p50: pct(a, 0.5), p95: pct(a, 0.95), p99: pct(a, 0.99), max: a[a.length - 1] ?? 0 };
}

export async function runBench(app: App): Promise<void> {
  const tour = app.tour;
  if (!tour) return;
  const note = el('div', { class: 'bench-note' }, '性能测量中：导览将自动播放约 3 分钟，请不要操作。');
  document.body.append(note);
  const all: number[] = [];
  const perStep: number[][] = [];
  let cur: number[] = [];
  let step = -1;
  let done = false;
  let last = performance.now();
  const sample = () => {
    const now = performance.now();
    const dt = now - last;
    last = now;
    if (step >= 0) {
      cur.push(dt);
      all.push(dt);
    }
    if (!done) requestAnimationFrame(sample);
  };
  requestAnimationFrame(sample);
  tour.onStep = (i) => {
    if (step >= 0) perStep[step] = cur;
    cur = [];
    step = i;
  };
  const t0 = performance.now();
  await tour.play(0);
  done = true;
  if (step >= 0) perStep[step] = cur;
  tour.onStep = null;
  note.remove();

  const r = app.engine.renderer;
  const size = r.getDrawingBufferSize(new (await import('three/webgpu')).Vector2());
  const report = {
    when: new Date().toISOString(),
    seconds: Math.round((performance.now() - t0) / 1000),
    backend: app.engine.backend,
    tier: app.tier,
    gpu: app.gpuInfo,
    userAgent: navigator.userAgent,
    screen: { css: [innerWidth, innerHeight], devicePixelRatio, render: [size.x, size.y], renderScale: r.getPixelRatio() },
    stream: app.nodes.stats,
    overall: summarise(-1, all),
    steps: perStep.map((t, i) => summarise(i, t ?? [])),
  };
  const json = JSON.stringify(report, null, 1);
  const f = (x: number) => x.toFixed(1);
  const rows = report.steps.map((s) => el('tr', {}, el('td', {}, s.label), el('td', {}, String(s.frames)), el('td', {}, f(s.p50)), el('td', {}, f(s.p95)), el('td', {}, f(s.max))));
  const copy = el('button', { class: 'bench-btn', onclick: () => void navigator.clipboard?.writeText(json).then(() => (copy.textContent = '已复制')) }, '复制结果（JSON）');
  const save = el('button', {
    class: 'bench-btn',
    onclick: () => {
      const a = el('a', { href: URL.createObjectURL(new Blob([json], { type: 'application/json' })), download: `stm-bench-${report.when.slice(0, 10)}.json` });
      a.click();
    },
  }, '下载');
  const o = report.overall;
  const panel = el('div', { class: 'bench-panel', role: 'dialog', 'aria-label': '性能测量结果' },
    el('h3', {}, '性能测量结果'),
    el('p', {}, `${report.backend === 'webgpu' ? 'WebGPU' : 'WebGL2'} · ${TIER_NAME[report.tier]}画质 · 渲染 ${size.x}×${size.y} · ${report.gpu ? `${report.gpu.vendor} ${report.gpu.architecture}`.trim() : '显卡信息不可用'}`),
    el('p', { class: 'bench-big' }, `帧时间 中位数 ${f(o.p50)} ms（约 ${Math.round(1000 / Math.max(o.p50, 0.1))} fps） · 95% ${f(o.p95)} ms · 最慢 ${f(o.max)} ms`),
    el('table', {}, el('thead', {}, el('tr', {}, el('th', {}, '步骤'), el('th', {}, '帧数'), el('th', {}, '中位 ms'), el('th', {}, '95% ms'), el('th', {}, '最慢 ms'))), el('tbody', {}, ...rows)),
    el('div', { class: 'bench-actions' }, copy, save, el('button', { class: 'bench-btn', onclick: () => panel.remove() }, '关闭')),
  );
  document.body.append(panel);
  (window as unknown as { __bench?: unknown }).__bench = report;
}
